<?php
require_once __DIR__.'/../config.php';require_admin();
$allowed=['pending','processed','shipped','completed','cancelled'];
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$status=$_POST['status'];if(in_array($status,$allowed,true)){$st=$conn->prepare("UPDATE orders SET status=? WHERE id=?");$st->bind_param("si",$status,$id);$st->execute();$_SESSION['flash']=['type'=>'success','message'=>'Status pesanan diperbarui.'];}redirect('orders.php');}
$rows=$conn->query("SELECT o.*,u.name customer_name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC");include '_header.php';?>
<h1 class="h3 fw-bold mb-4">Kelola Pesanan</h1><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>No.</th><th>Pelanggan</th><th>Total</th><th>Tanggal</th><th>Status</th><th>Ubah status</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td>#<?=$r['id']?></td><td><?=e($r['customer_name'])?><div class="small-muted"><?=e($r['phone'])?></div></td><td><?=rupiah($r['total_amount'])?></td><td><?=date('d-m-Y',strtotime($r['created_at']))?></td><td><?=e($r['status'])?></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="id" value="<?=$r['id']?>"><select class="form-select form-select-sm" name="status"><?php foreach($allowed as $s):?><option value="<?=$s?>" <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-sm btn-success">Simpan</button></form></td></tr><?php endwhile;?></tbody></table></div></div><?php include '_footer.php';?>